async function submitOrder(e){e.preventDefault();sBusy(true);sError("");const items=[];for(const p of cart){const prints=[];for(const x of p.prints)prints.push({position:x.position,size_code:x.size_code,design_base64:await file64(x.file),design_name:x.file.name,transform:x.transform});items.push({product_id:p.id,quantity:p.qty,sizes:Object.entries(p.sizes||{}).filter(x=>+x[1]>0).map(([size,quantity])=>({size,quantity:+quantity})),color:p.color,placement:p.placement,garment_type:p.garment_type,printing_method:"DTF",prints})}const{data,error}=await supabase.functions.invoke("showroom-public-api",{body:{action:"create_order",customer,deposit_amount:Math.max(0,Number(customer.deposit_amount)||0),items}});sBusy(false);if(error||data?.error){sError(data?.error||error?.message||"Pesanan gagal.");return}const receiptItems=cart.map(p=>({product_name_snapshot:p.name,model:p.model||"OBLONG",garment_type:p.garment_type,material:p.material||p.showroom_materials?.name||"Sesuai katalog",color:p.color,color_hex:mockups.find(m=>m.garment_type===p.garment_type&&m.color_name===p.color)?.color_hex||"#ffffff",quantity:p.qty,sizes:Object.entries(p.sizes||{}).filter(([,v])=>+v>0).map(([size,quantity])=>({size,quantity:+quantity})),placement:p.placement,print_positions:p.print_positions,prints:p.prints.map(x=>({position:x.position,size_code:x.size_code,preview:x.preview,transform:x.transform})),printing_method:"DTF",mockup:p.mockup}));sReceipt({...data,customer:{...customer},items:receiptItems});sCheckout(false);sCart([]);window.open("https://wa.me/"+WA+"?text="+encodeURIComponent("Halo SANDIKALE, saya telah mengirim pesanan.\nOrder: "+data.order_number+"\nSPK: "+data.spk_number+"\nTracking: "+data.tracking_code+"\nMohon konfirmasi."),"_blank","noopener,noreferrer")}
async function decideDesign(id,decision){const notes=decision==="revision_requested"?window.prompt("Jelaskan revisi desain yang diperlukan:",""): "";if(notes===null)return;const{data,error}=await supabase.functions.invoke("showroom-public-api",{body:{action:"design_decision",tracking_code:tracking,design_id:id,decision,notes}});if(error||data?.error){sError(data?.error||error?.message||"Keputusan desain gagal disimpan.");return}await trackOrder(tracking)}
