async function saveProduct(e){e.preventDefault();const f=new FormData(e.currentTarget),name=String(f.get("name")||"").trim(),photo=f.get("photo"),frontPhoto=f.get("photo_front"),backPhoto=f.get("photo_back"),payload={name,slug:slug(name),description:f.get("description"),base_price:+f.get("base_price"),long_sleeve_price:f.get("long_sleeve_price")===""?null:Math.max(0,+f.get("long_sleeve_price")),size_surcharges:{XXL:Math.max(0,+f.get("surcharge_xxl")||0),XXXL:Math.max(0,+f.get("surcharge_xxxl")||0)},model:f.get("model"),material_id:f.get("material_id")||null,available_colors:String(f.get("available_colors")||"").split(",").map(x=>x.trim()).filter(Boolean),category_id:f.get("category_id")||null,is_published:f.get("published")==="on",stock_mode:"made_to_order"};if(!name||payload.base_price<0){sError("Nama dan harga produk wajib valid.");return}if(photo instanceof File&&photo.size&&(!["image/jpeg","image/png","image/webp"].includes(photo.type)||photo.size>10*1024*1024)){sError("Foto harus JPG, PNG, WEBP dan maksimal 10 MB.");return}if(payload.is_published&&!payload.available_colors.length){sError("Tambahkan minimal satu warna yang tersedia sebelum menerbitkan katalog.");return}if(payload.is_published&&!photo.size&&!edit?.showroom_product_images?.some(x=>x.is_primary)){sError("Unggah foto produk utama terlebih dahulu sebelum menerbitkan katalog.");return}for(const [label,file] of [["depan",frontPhoto],["belakang",backPhoto]])if(file instanceof File&&file.size&&(!["image/jpeg","image/png","image/webp"].includes(file.type)||file.size>10*1024*1024)){sError("Foto mockup "+label+" harus JPG, PNG, WEBP dan maksimal 10 MB.");return}let productId=edit?.id;if(productId){const{error}=await supabase.from("showroom_products").update(payload).eq("id",productId);if(error){sError(error.message);return}}else{const{data,error}=await supabase.from("showroom_products").insert(payload).select("id").single();if(error){sError(error.message);return}productId=data.id}if(photo instanceof File&&photo.size){const ext=photo.type==="image/png"?"png":photo.type==="image/webp"?"webp":"jpg",path=productId+"/"+crypto.randomUUID()+"."+ext;const{data:uploaded,error:uploadError}=await supabase.storage.from("showroom-product-images").upload(path,photo,{contentType:photo.type,upsert:false});if(uploadError){sError("Foto gagal diunggah: "+uploadError.message);return}await supabase.from("showroom_product_images").update({is_primary:false}).eq("product_id",productId);const{error:imageError}=await supabase.from("showroom_product_images").insert({product_id:productId,storage_path:uploaded.path,is_primary:true,sort_order:0,alt_text:name});if(imageError){sError("Data foto gagal disimpan: "+imageError.message);return}}for(const [file,label] of [[frontPhoto,"SPK FRONT"],[backPhoto,"SPK BACK"]]){if(file instanceof File&&file.size){const ext=file.type==="image/png"?"png":file.type==="image/webp"?"webp":"jpg",path=productId+"/spk-"+label.toLowerCase().replace(" ","-")+"-"+crypto.randomUUID()+"."+ext;const{data:uploaded,error:uploadError}=await supabase.storage.from("showroom-product-images").upload(path,file,{contentType:file.type,upsert:false});if(uploadError){sError("Foto mockup "+label+" gagal diunggah: "+uploadError.message);return}const{error:imageError}=await supabase.from("showroom_product_images").insert({product_id:productId,storage_path:uploaded.path,is_primary:false,sort_order:label==="SPK FRONT"?1:2,alt_text:label});if(imageError){sError("Data mockup "+label+" gagal disimpan: "+imageError.message);return}}}sEdit(null);sError("");loadAdminProducts()}
