async function productionStatus(o,v){const stageMap={new:"order_confirmed",design_confirmation:"design_approved",waiting_production:"material_preparation",in_production:"printing",printing:"printing",finishing:"finishing",quality_control:"quality_control",completed:"completed",ready_for_pickup:"ready",handed_over:"completed",cancelled:"completed"};const{error}=await supabase.from("showroom_orders").update({production_status:v,updated_at:new Date().toISOString()}).eq("id",o.id);if(error){sError(error.message);return}let job=Array.isArray(o.showroom_production_jobs)?o.showroom_production_jobs[0]:o.showroom_production_jobs;if(!job){const{data,error:je}=await supabase.from("showroom_production_jobs").insert({order_id:o.id,current_stage:stageMap[v]||"order_confirmed",notes:"Job produksi dibuat dari dashboard."}).select("id").single();if(je){sError(je.message);return}job=data}const{error:je}=await supabase.from("showroom_production_jobs").update({current_stage:stageMap[v]||"order_confirmed",updated_at:new Date().toISOString(),actual_completion:["completed","handed_over"].includes(v)?new Date().toISOString():null}).eq("id",job.id);if(je){sError(je.message);return}const{error:ue}=await supabase.from("showroom_production_updates").insert({production_job_id:job.id,stage:stageMap[v]||"order_confirmed",description:"Status produksi diperbarui: "+(productionStages.find(x=>x[0]===v)?.[1]||v),updated_by:profile?.id||null});if(ue){sError(ue.message);return}await loadOrders()}

async function uploadDesignRevision(orderId,design,file){if(!file)return;if(!["image/jpeg","image/png","image/webp","application/pdf"].includes(file.type)||file.size>8*1024*1024){sError("Revisi harus JPG, PNG, WEBP, atau PDF maksimal 8 MB.");return}const ext=file.type==="image/jpeg"?"jpg":file.type==="image/png"?"png":file.type==="image/webp"?"webp":"pdf",path="orders/"+orderId+"/"+crypto.randomUUID()+"-revision."+ext;const{data:uploaded,error:uploadError}=await supabase.storage.from("showroom-customer-designs").upload(path,file,{contentType:file.type,upsert:false});if(uploadError){sError(uploadError.message);return}const next=Number(design.design_version||1)+1,{error:updateError}=await supabase.from("showroom_order_designs").update({original_storage_path:uploaded.path,design_version:next,approval_status:"waiting_customer"}).eq("id",design.id);if(updateError){sError(updateError.message);return}const{error:approvalError}=await supabase.from("showroom_design_approvals").upsert({order_id:orderId,order_design_id:design.id,revision_number:next,approval_status:"waiting",approved_by_customer:false,notes:"Revisi artwork diunggah admin."},{onConflict:"order_design_id,revision_number"});if(approvalError){sError(approvalError.message);return}const{error:statusError}=await supabase.from("showroom_orders").update({status:"waiting_customer_approval",updated_at:new Date().toISOString()}).eq("id",orderId);if(statusError)sError(statusError.message);else loadOrders()}
async function generateAdminSpk(o){try{const items=[];for(const item of o.showroom_order_items||[]){const prints=[];for(const design of item.showroom_order_designs||[]){const{data:signed}=await supabase.storage.from("showroom-customer-designs").createSignedUrl(design.original_storage_path,600);const cfg=design.design_configuration||{};prints.push({position:cfg.placement||"Depan - Tengah",size_code:cfg.size_code||"",preview:signed?.signedUrl||null,transform:cfg.transform||null})}const cfg=item.specification||{},mock=mockups.find(m=>m.garment_type===cfg.garment_type&&m.color_name===cfg.color),front=mock?mockupUrl(mock.front_storage_path):null,back=mock?mockupUrl(mock.back_storage_path):null;items.push({product_name_snapshot:item.product_name_snapshot,model:item.model_snapshot||"CUSTOM",material:item.material_snapshot||"Sesuai katalog",garment_type:cfg.garment_type||"short",color:item.color||cfg.color||"-",color_hex:mock?.color_hex||"#ffffff",quantity:item.quantity,sizes:(item.showroom_order_variants||[]).map(v=>({size:v.size,quantity:v.quantity})),placement:cfg.placement||"",printing_method:"DTF",prints,mockup:{front,back}})}const{data:payments}=await supabase.from("showroom_payments").select("amount").eq("order_id",o.id).eq("payment_status","verified");const paid=(payments||[]).reduce((n,p)=>n+Number(p.amount||0),0);await spk({order_id:o.id,order_number:o.order_number,spk_number:o.spk_number,version:o.version,total_quantity:items.reduce((n,x)=>n+(+x.quantity||0),0),total_amount:o.total_amount,deposit_amount:paid,remaining_amount:Math.max(0,Number(o.total_amount)-paid),customer:{name:o.showroom_customers?.name,phone:o.showroom_customers?.whatsapp,address:o.showroom_customers?.address,organization:o.showroom_customers?.organization,notes:o.notes},items,production_status:o.production_status})}catch(err){sError("SPK tidak dapat dibuat: "+(err?.message||"periksa data pesanan"))}}
async function openSpk(path){const{data,error}=await supabase.storage.from("showroom-spk-documents").createSignedUrl(path,600);if(error){sError(error.message);return}window.open(data.signedUrl,"_blank","noopener,noreferrer")}async function openDesign(path){const{data,error}=await supabase.storage.from("showroom-customer-designs").createSignedUrl(path,600);if(error){sError(error.message);return}window.open(data.signedUrl,"_blank","noopener,noreferrer")}
async function verifyPayment(o){const{data:payments,error:paymentReadError}=await supabase.from("showroom_payments").select("*").eq("order_id",o.id).order("created_at",{ascending:true});if(paymentReadError){sError(paymentReadError.message);return}let verified=(payments||[]).filter(p=>p.payment_status==="verified").reduce((sum,p)=>sum+Number(p.amount||0),0);const pending=(payments||[]).filter(p=>p.payment_status==="waiting_verification");if(pending.length){const pendingTotal=pending.reduce((sum,p)=>sum+Number(p.amount||0),0);if(!window.confirm("Verifikasi pembayaran masuk sebesar "+money(pendingTotal)+"?"))return;const{error}=await supabase.from("showroom_payments").update({payment_status:"verified",paid_at:new Date().toISOString(),verified_by:profile?.id||null}).in("id",pending.map(p=>p.id));if(error){sError(error.message);return}verified+=pendingTotal}else{const remaining=Math.max(0,Number(o.total_amount)-verified);if(remaining<=0){sError("Pesanan ini sudah lunas.");return}const raw=window.prompt("Masukkan nominal pembayaran yang sudah diterima (Rp). Sisa tagihan: "+money(remaining),String(remaining));if(raw===null)return;const amount=Number(String(raw).replace(/[^0-9]/g,""));if(!Number.isFinite(amount)||amount<=0||amount>remaining){sError("Nominal harus lebih dari nol dan tidak boleh melebihi sisa tagihan "+money(remaining)+".");return}const{error}=await supabase.from("showroom_payments").insert({order_id:o.id,amount,payment_method:"manual",payment_status:"verified",paid_at:new Date().toISOString(),verified_by:profile?.id||null,notes:"Diverifikasi manual oleh admin."});if(error){sError(error.message);return}verified+=amount}const next=verified>=Number(o.total_amount)?"paid":verified>0?"partially_paid":"unpaid";const{error:oe}=await supabase.from("showroom_orders").update({payment_status:next,status:next==="paid"?"paid":o.status,updated_at:new Date().toISOString()}).eq("id",o.id);if(oe)sError(oe.message);else loadOrders()}
if(admin)return <div className="admin"><header className="top"><Brand/><a href={import.meta.env.BASE_URL}>Buka showroom ↗</a></header>{!session?<form className="login" onSubmit={login}><small>PRIVATE WORKSPACE</small><h1>Admin showroom</h1><label>Email<input type="email" required value={credentials.email} onChange={e=>sCredentials({...credentials,email:e.target.value})}/></label><label>Password<input type="password" required value={credentials.password} onChange={e=>sCredentials({...credentials,password:e.target.value})}/></label>{error&&<p className="error">{error}</p>}<Btn disabled={busy}>Masuk</Btn></form>:!profile?<div className="login">Akun belum memiliki profil showroom aktif. Hubungi Owner.</div>:<><div className="admin-head"><div><small>SANDIKALE / CONTROL ROOM</small><h1>Dashboard operasional</h1></div><Btn onClick={()=>supabase.auth.signOut()}>Keluar</Btn></div><nav className="tabs">{[["orders","Pesanan"],["products","Katalog"],["tracking","Tracking"],["settings","Pengaturan"]].map(([k,v])=><button className={tab===k?"active":""} onClick={()=>sTab(k)}>{v}</button>)}</nav><main className="admin-body">{tab==="orders"&&<><div className="stats"><article><small>Total order</small><b>{orders.length}</b></article><article><small>Aktif</small><b>{orders.filter(o=>!["completed","cancelled"].includes(o.status)).length}</b></article><article><small>Belum dibayar</small><b>{orders.filter(o=>o.payment_status==="unpaid").length}</b></article></div><div className="tablebox"><table><thead><tr><th>Order / SPK</th><th>Pelanggan</th><th>Total</th><th>Status order</th><th>Produksi</th><th>Pembayaran</th><th>Ubah</th></tr></thead><tbody>{orders.map(o=><tr><td><b>{o.order_number}</b><small>{o.spk_number}</small>{(o.showroom_order_items||[]).flatMap(i=>i.showroom_order_designs||[]).map(d=><><button className="linkbtn" onClick={()=>openDesign(d.original_storage_path)}>Buka Artwork</button><label className="linkbtn">Unggah revisi<input type="file" accept="image/jpeg,image/png,image/webp,application/pdf" hidden onChange={e=>uploadDesignRevision(o.id,d,e.target.files?.[0])}/></label></>)}{(o.showroom_spk_documents||[]).map(d=><button className="linkbtn" onClick={()=>openSpk(d.storage_path)}>SPK r{d.revision_number} · {d.document_status==="active"?"Aktif":"Arsip"}</button>)}{["owner","admin"].includes(profile?.role)&&<button className="linkbtn" onClick={()=>generateAdminSpk(o)}>Generate SPK terbaru</button>}</td><td>{o.showroom_customers?.name}<small>{o.showroom_customers?.whatsapp}</small></td><td>{money(o.total_amount)}</td><td>{labels[o.status]||o.status}<small>{o.payment_status||"unpaid"}</small></td><td><select value={o.production_status||"new"} onChange={e=>productionStatus(o,e.target.value)}>{productionStages.map(([k,v])=><option value={k}>{v}</option>)}</select></td><td>{o.payment_status==="paid"?"LUNAS":<Btn onClick={()=>verifyPayment(o)}>Verifikasi bayar</Btn>}</td><td><select value={o.status} onChange={e=>status(o,e.target.value)}>{Object.entries(labels).map(([k,v])=><option value={k}>{v}</option>)}</select></td></tr>)}</tbody></table></div></>}{tab==="products"&&<><div className="toolbar"><h2>Kelola katalog</h2><Btn onClick={()=>sEdit({})}>+ Produk baru</Btn></div>{adminProducts.map(p=><div className="product-row">{p.showroom_product_images?.find(x=>x.is_primary)?.storage_path?<img className="admin-product-thumb" src={supabase.storage.from("showroom-product-images").getPublicUrl(p.showroom_product_images.find(x=>x.is_primary).storage_path).data.publicUrl} alt={p.name}/>:<span className="admin-product-thumb empty-thumb">NO PHOTO</span>}<div><b>{p.name}</b><small>{money(p.base_price)} · {p.is_published?"Terbit":"Draft"}</small></div><Btn onClick={()=>sEdit(p)}>Edit</Btn><Btn onClick={async()=>{if(!p.is_published&&!p.showroom_product_images?.some(x=>x.is_primary)){sError("Produk belum bisa diterbitkan. Unggah foto katalog terlebih dahulu.");return}const{error}=await supabase.from("showroom_products").update({is_published:!p.is_published}).eq("id",p.id);if(error)sError(error.message);else{sError("");loadAdminProducts()}}}>{p.is_published?"Sembunyikan":"Terbitkan"}</Btn></div>)}{edit&&<form className="edit-form" onSubmit={saveProduct}><h3>{edit.id?"Edit produk":"Tambah produk"}</h3><label>Nama<input name="name" defaultValue={edit.name||""} required/></label><label>Harga lengan pendek<input name="base_price" type="number" min="0" defaultValue={edit.base_price||85000} required/></label><label>Harga lengan panjang (opsional)<input name="long_sleeve_price" type="number" min="0" defaultValue={edit.long_sleeve_price??""} placeholder="Kosongkan jika sama dengan harga dasar"/></label><label>Tambahan ukuran XXL<input name="surcharge_xxl" type="number" min="0" defaultValue={edit.size_surcharges?.XXL||0}/></label><label>Tambahan ukuran XXXL<input name="surcharge_xxxl" type="number" min="0" defaultValue={edit.size_surcharges?.XXXL||0}/></label><label>Model<input name="model" defaultValue={edit.model||"Oblong"}/></label><label>Jenis bahan<select name="material_id" defaultValue={edit.material_id||""}><option value="">Pilih bahan katalog</option>{materials.map(m=><option value={m.id}>{m.name}</option>)}</select></label><label>Warna tersedia (pisahkan dengan koma)<input name="available_colors" defaultValue={(edit.available_colors||[]).map(c=>typeof c==="string"?c:c.name).join(", ")} placeholder="Putih, Hitam, Navy"/></label><label>Kategori<select name="category_id" defaultValue={edit.category_id||""}><option value="">Tanpa kategori</option>{categories.map(cat=><option value={cat.id}>{cat.name}</option>)}</select></label><label>Deskripsi<textarea name="description" defaultValue={edit.description||""}/></label><label>Foto katalog (wajib · JPG/PNG/WEBP · maks. 10 MB)<input name="photo" type="file" accept="image/jpeg,image/png,image/webp" required={!edit?.showroom_product_images?.some(x=>x.is_primary)}/>{edit?.showroom_product_images?.find(x=>x.is_primary)?.storage_path&&<small>Foto utama sudah tersimpan.</small>}</label><label className="check"><input name="published" type="checkbox" defaultChecked={edit.is_published}/> Terbitkan</label><Btn>Simpan</Btn><Btn type="button" onClick={()=>sEdit(null)}>Batal</Btn></form>}</>}{tab==="tracking"&&<><h2>Tracking pesanan</h2><p>Pelanggan dapat melacak pesanan melalui kode tracking pada SPK.</p></>}{tab==="settings"&&<><h2>Pengaturan produksi</h2><p>WhatsApp admin: +62 822-6641-2844 · Pembayaran manual.</p><h3>Daftar bahan produk</h3><form className="edit-form" onSubmit={saveMaterial}><label>Nama bahan<input name="name" required placeholder="Cotton Combed 30s"/></label><label>Deskripsi<input name="description" placeholder="Gramasi / karakter bahan"/></label><label>Biaya tambahan bahan (Rp)<input name="surcharge" type="number" min="0" defaultValue="0"/></label><Btn>Tambah bahan</Btn></form><div className="dtf-rate-list">{materials.map(m=><div className="dtf-rate"><b>{m.name}</b><small>{money(m.surcharge||0)}</small></div>)}</div><h3>Tarif sablon DTF</h3><p>Isi harga per lembar berdasarkan ukuran cetak. Tarif ini otomatis ditambahkan untuk setiap posisi sablon dan dikalikan jumlah kaos.</p><div className="dtf-rate-list">{dtfPrices.map(rate=><div className="dtf-rate" key={rate.id}><b>{rate.label}</b><input type="number" min="0" value={rate.price} onChange={e=>sDtfPrices(old=>old.map(x=>x.id===rate.id?{...x,price:+e.target.value}:x))}/><Btn onClick={()=>saveDtfRate(rate)}>Simpan</Btn></div>)}</div><h3>Mockup kaos berdasarkan warna</h3><p>Unggah mockup depan dan belakang yang sesuai. File transparan PNG disarankan agar pratinjau warna tetap akurat.</p><form className="edit-form" onSubmit={saveMockup}><label>Model kaos<select name="garment_type" required><option value="">Pilih model</option><option value="short">Lengan pendek</option><option value="long">Lengan panjang</option></select></label><label>Nama warna<input name="color_name" required placeholder="Putih / Hitam / Navy"/></label><label>Kode warna<input name="color_hex" type="color" defaultValue="#ffffff"/></label><label>File pasangan mockup (depan di kiri, belakang di kanan)<input name="pair" type="file" accept="image/png,image/jpeg,image/webp" required/><small>Unggah file asli yang Anda berikan. Sistem memisahkan kedua sisi otomatis tanpa meregangkan gambar.</small></label><Btn>Simpan mockup warna</Btn></form><div className="mockup-admin-list">{mockups.map(m=><p>{m.garment_type==="long"?"Lengan panjang":"Lengan pendek"} · {m.color_name} <small>{m.color_hex}</small></p>)}</div></>}</main></>}{error&&<div className="toast-message" role="alert"><span>{error}</span><button type="button" aria-label="Tutup pesan" onClick={()=>sError("")}>×</button></div>}</div>;
